pub fn write_ecinfo(w: &mut Writer<'_>, value: &ECInfo, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("ECInfo");
    for required in w.required(restriction) {
        let present = match required {
            Name::Name => value.name.is_some(),
            Name::LblEC => value.lbl_ec.is_some(),
            Name::ECType => value.ec_type.is_some(),
            Name::ECMethod => value.ec_method.is_some(),
            Name::Date => value.date.is_some(),
            Name::Cur => value.cur.is_some(),
            Name::CurLbl => value.cur_lbl.is_some(),
            Name::DateOfInformation => value.date_of_information.is_some(),
            Name::DateOfPrice => value.date_of_price.is_some(),
            Name::ECBkdn => !value.ec_bkdn.is_empty(),
            Name::Ctlg => !value.ctlg.is_empty(),
            Name::ConsortiumMember => !value.consortium_member.is_empty(),
            Name::CtlgAssign => !value.ctlg_assign.is_empty(),
            Name::Totals => value.totals.is_some(),
            Name::AddText => !value.add_text.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("ECInfo", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_ecinfo(w.version());
    let mut cursor = [0usize; 15];
    for name in order {
        while field_ecinfo(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.name.is_some() && cursor[0] == 0 {
        w.dropped("ECInfo", "Name");
    }
    if value.lbl_ec.is_some() && cursor[1] == 0 {
        w.dropped("ECInfo", "LblEC");
    }
    if value.ec_type.is_some() && cursor[2] == 0 {
        w.dropped("ECInfo", "ECType");
    }
    if value.ec_method.is_some() && cursor[3] == 0 {
        w.dropped("ECInfo", "ECMethod");
    }
    if value.date.is_some() && cursor[4] == 0 {
        w.dropped("ECInfo", "Date");
    }
    if value.cur.is_some() && cursor[5] == 0 {
        w.dropped("ECInfo", "Cur");
    }
    if value.cur_lbl.is_some() && cursor[6] == 0 {
        w.dropped("ECInfo", "CurLbl");
    }
    if value.date_of_information.is_some() && cursor[7] == 0 {
        w.dropped("ECInfo", "DateOfInformation");
    }
    if value.date_of_price.is_some() && cursor[8] == 0 {
        w.dropped("ECInfo", "DateOfPrice");
    }
    if value.ec_bkdn.len() > cursor[9] {
        w.dropped("ECInfo", "ECBkdn");
    }
    if value.ctlg.len() > cursor[10] {
        w.dropped("ECInfo", "Ctlg");
    }
    if value.consortium_member.len() > cursor[11] {
        w.dropped("ECInfo", "ConsortiumMember");
    }
    if value.ctlg_assign.len() > cursor[12] {
        w.dropped("ECInfo", "CtlgAssign");
    }
    if value.totals.is_some() && cursor[13] == 0 {
        w.dropped("ECInfo", "Totals");
    }
    if value.add_text.len() > cursor[14] {
        w.dropped("ECInfo", "AddText");
    }
    w.extra(&value.extra, "ECInfo");
    w.close(tag);
    Ok(())
}

