pub fn write_ftexttc(w: &mut Writer<'_>, value: &FTextTC, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("FTextTC");
    for required in w.required(restriction) {
        let present = match required {
            Name::P => !value.p.is_empty(),
            Name::Div => !value.div.is_empty(),
            Name::Span => !value.span.is_empty(),
            Name::Ul => !value.ul.is_empty(),
            Name::Ol => !value.ol.is_empty(),
            Name::Table => !value.table.is_empty(),
            Name::Br => !value.br.is_empty(),
            Name::Page => !value.page.is_empty(),
            Name::Image => !value.image.is_empty(),
            Name::TextComplement => !value.text_complement.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("FTextTC", *required, value.node)?;
        }
    }
    w.open(tag);
    if let Some(v) = value.style {
        w.attr_span("style", v);
    }
    if let Some(v) = value.text_width {
        w.attr_span("textWidth", v);
    }
    w.open_end();
    let order = order_ftexttc(w.version());
    let mut cursor = [0usize; 10];
    let groups: &[&[Name]] = &[
        &[
            Name::P,
            Name::Div,
            Name::Span,
            Name::Ul,
            Name::Ol,
            Name::Table,
            Name::Br,
            Name::Page,
            Name::Image,
            Name::TextComplement,
        ],
        &[
            Name::P,
            Name::Div,
            Name::Span,
            Name::Ul,
            Name::Ol,
            Name::Table,
            Name::Br,
            Name::Page,
            Name::Image,
        ],
    ];
    let mut done = [false; 2];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_ftexttc(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_ftexttc(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_ftexttc(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.p.len() > cursor[0] {
        w.dropped("FTextTC", "p");
    }
    if value.div.len() > cursor[1] {
        w.dropped("FTextTC", "div");
    }
    if value.span.len() > cursor[2] {
        w.dropped("FTextTC", "span");
    }
    if value.ul.len() > cursor[3] {
        w.dropped("FTextTC", "ul");
    }
    if value.ol.len() > cursor[4] {
        w.dropped("FTextTC", "ol");
    }
    if value.table.len() > cursor[5] {
        w.dropped("FTextTC", "table");
    }
    if value.br.len() > cursor[6] {
        w.dropped("FTextTC", "br");
    }
    if value.page.len() > cursor[7] {
        w.dropped("FTextTC", "page");
    }
    if value.image.len() > cursor[8] {
        w.dropped("FTextTC", "Image");
    }
    if value.text_complement.len() > cursor[9] {
        w.dropped("FTextTC", "TextComplement");
    }
    w.extra(&value.extra, "FTextTC");
    w.close(tag);
    Ok(())
}

