pub fn write_itemlist(w: &mut Writer<'_>, value: &Itemlist, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("Itemlist");
    for required in w.required(restriction) {
        let present = match required {
            Name::Remark => !value.remark.is_empty(),
            Name::PerfDescr => !value.perf_descr.is_empty(),
            Name::Item => !value.item.is_empty(),
            Name::MarkupItem => !value.markup_item.is_empty(),
            Name::MastAgrItems => !value.mast_agr_items.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("Itemlist", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_itemlist(w.version());
    let mut cursor = [0usize; 5];
    let groups: &[&[Name]] = &[
        &[
            Name::Remark,
            Name::PerfDescr,
            Name::Item,
            Name::MarkupItem,
            Name::MastAgrItems,
        ],
        &[Name::Remark, Name::PerfDescr, Name::Item, Name::MarkupItem],
    ];
    let mut done = [false; 2];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_itemlist(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_itemlist(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_itemlist(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.remark.len() > cursor[0] {
        w.dropped("Itemlist", "Remark");
    }
    if value.perf_descr.len() > cursor[1] {
        w.dropped("Itemlist", "PerfDescr");
    }
    if value.item.len() > cursor[2] {
        w.dropped("Itemlist", "Item");
    }
    if value.markup_item.len() > cursor[3] {
        w.dropped("Itemlist", "MarkupItem");
    }
    if value.mast_agr_items.len() > cursor[4] {
        w.dropped("Itemlist", "MastAgrItems");
    }
    w.extra(&value.extra, "Itemlist");
    w.close(tag);
    Ok(())
}

