pub fn write_mastagritems(
    w: &mut Writer<'_>,
    value: &MastAgrItems,
    tag: &str,
) -> Result<(), WriteError> {
    let restriction = w.restriction("MastAgrItems");
    for required in w.required(restriction) {
        let present = match required {
            Name::HourItem => !value.hour_item.is_empty(),
            Name::MaterialItem => !value.material_item.is_empty(),
            Name::MarkupItemOWN => !value.markup_item_own.is_empty(),
            Name::MarkupItemCTR => !value.markup_item_ctr.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("MastAgrItems", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_mastagritems(w.version());
    let mut cursor = [0usize; 4];
    let groups: &[&[Name]] = &[&[
        Name::HourItem,
        Name::MaterialItem,
        Name::MarkupItemOWN,
        Name::MarkupItemCTR,
    ]];
    let mut done = [false; 1];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_mastagritems(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_mastagritems(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_mastagritems(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.hour_item.len() > cursor[0] {
        w.dropped("MastAgrItems", "HourItem");
    }
    if value.material_item.len() > cursor[1] {
        w.dropped("MastAgrItems", "MaterialItem");
    }
    if value.markup_item_own.len() > cursor[2] {
        w.dropped("MastAgrItems", "MarkupItemOWN");
    }
    if value.markup_item_ctr.len() > cursor[3] {
        w.dropped("MastAgrItems", "MarkupItemCTR");
    }
    w.extra(&value.extra, "MastAgrItems");
    w.close(tag);
    Ok(())
}

