    w.open_end();
    let order = order_materialitem(w.version());
    let mut cursor = [0usize; 4];
    for name in order {
        while field_materialitem(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.pred_it.is_some() && cursor[0] == 0 {
        w.dropped("MaterialItem", "PredIT");
    }
