pub fn write_orderinfo(w: &mut Writer<'_>, value: &OrderInfo, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("OrderInfo");
    for required in w.required(restriction) {
        let present = match required {
            Name::Inquiry => value.inquiry.is_some(),
            Name::CallOrder => value.call_order.is_some(),
            Name::RepOrder => value.rep_order.is_some(),
            Name::InquiryNo => value.inquiry_no.is_some(),
            Name::OfferNo => value.offer_no.is_some(),
            Name::PartNo => value.part_no.is_some(),
            Name::OrderConfNo => value.order_conf_no.is_some(),
            Name::TenderDate => value.tender_date.is_some(),
            Name::DeliveryType => value.delivery_type.is_some(),
            Name::DeliveryWeek => value.delivery_week.is_some(),
            Name::DeliveryDate => value.delivery_date.is_some(),
            Name::DeliveryTime => value.delivery_time.is_some(),
            Name::FixedPriceDate => value.fixed_price_date.is_some(),
            Name::ModeOfShipment => value.mode_of_shipment.is_some(),
            Name::Cur => value.cur.is_some(),
            Name::CurLbl => value.cur_lbl.is_some(),
            Name::AddText => value.add_text.is_some(),
            Name::OfferFixedPriceDate => value.offer_fixed_price_date.is_some(),
            Name::OfferFixedPriceWeek => value.offer_fixed_price_week.is_some(),
            Name::CustomerBoQBkdn => !value.customer_boq_bkdn.is_empty(),
            Name::SupplierBoQBkdn => !value.supplier_boq_bkdn.is_empty(),
            Name::PriceModification => !value.price_modification.is_empty(),
            Name::VAT => value.vat.is_some(),
            Name::CashDiscount => !value.cash_discount.is_empty(),
            Name::Quotation => !value.quotation.is_empty(),
            Name::SpecialPayTime => value.special_pay_time.is_some(),
            Name::Ctlg => !value.ctlg.is_empty(),
            Name::CustomerReferenceNo => value.customer_reference_no.is_some(),
            Name::SupplierReferenceNo => value.supplier_reference_no.is_some(),
            Name::DeliveryNo => value.delivery_no.is_some(),
            Name::DeliveryNoteVoucherDate => value.delivery_note_voucher_date.is_some(),
            Name::TotalWeight => value.total_weight.is_some(),
            Name::UW => value.uw.is_some(),
            Name::ProvisionDate => value.provision_date.is_some(),
            Name::CtlgAssign => !value.ctlg_assign.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("OrderInfo", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_orderinfo(w.version());
    let mut cursor = [0usize; 35];
    for name in order {
        while field_orderinfo(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.inquiry.is_some() && cursor[0] == 0 {
        w.dropped("OrderInfo", "Inquiry");
    }
    if value.call_order.is_some() && cursor[1] == 0 {
        w.dropped("OrderInfo", "CallOrder");
    }
    if value.rep_order.is_some() && cursor[2] == 0 {
        w.dropped("OrderInfo", "RepOrder");
    }
    if value.inquiry_no.is_some() && cursor[3] == 0 {
        w.dropped("OrderInfo", "InquiryNo");
    }
    if value.offer_no.is_some() && cursor[4] == 0 {
        w.dropped("OrderInfo", "OfferNo");
    }
    if value.part_no.is_some() && cursor[5] == 0 {
        w.dropped("OrderInfo", "PartNo");
    }
    if value.order_conf_no.is_some() && cursor[6] == 0 {
        w.dropped("OrderInfo", "OrderConfNo");
    }
    if value.tender_date.is_some() && cursor[7] == 0 {
        w.dropped("OrderInfo", "TenderDate");
    }
    if value.delivery_type.is_some() && cursor[8] == 0 {
        w.dropped("OrderInfo", "DeliveryType");
    }
    if value.delivery_week.is_some() && cursor[9] == 0 {
        w.dropped("OrderInfo", "DeliveryWeek");
    }
    if value.delivery_date.is_some() && cursor[10] == 0 {
        w.dropped("OrderInfo", "DeliveryDate");
    }
    if value.delivery_time.is_some() && cursor[11] == 0 {
        w.dropped("OrderInfo", "DeliveryTime");
    }
    if value.fixed_price_date.is_some() && cursor[12] == 0 {
        w.dropped("OrderInfo", "FixedPriceDate");
    }
    if value.mode_of_shipment.is_some() && cursor[13] == 0 {
        w.dropped("OrderInfo", "ModeOfShipment");
    }
    if value.cur.is_some() && cursor[14] == 0 {
        w.dropped("OrderInfo", "Cur");
    }
    if value.cur_lbl.is_some() && cursor[15] == 0 {
        w.dropped("OrderInfo", "CurLbl");
    }
    if value.add_text.is_some() && cursor[16] == 0 {
        w.dropped("OrderInfo", "AddText");
    }
    if value.offer_fixed_price_date.is_some() && cursor[17] == 0 {
        w.dropped("OrderInfo", "OfferFixedPriceDate");
    }
    if value.offer_fixed_price_week.is_some() && cursor[18] == 0 {
        w.dropped("OrderInfo", "OfferFixedPriceWeek");
    }
    if value.customer_boq_bkdn.len() > cursor[19] {
        w.dropped("OrderInfo", "CustomerBoQBkdn");
    }
    if value.supplier_boq_bkdn.len() > cursor[20] {
        w.dropped("OrderInfo", "SupplierBoQBkdn");
    }
    if value.price_modification.len() > cursor[21] {
        w.dropped("OrderInfo", "PriceModification");
    }
    if value.vat.is_some() && cursor[22] == 0 {
        w.dropped("OrderInfo", "VAT");
    }
    if value.cash_discount.len() > cursor[23] {
        w.dropped("OrderInfo", "CashDiscount");
    }
    if value.quotation.len() > cursor[24] {
        w.dropped("OrderInfo", "Quotation");
    }
    if value.special_pay_time.is_some() && cursor[25] == 0 {
        w.dropped("OrderInfo", "SpecialPayTime");
    }
    if value.ctlg.len() > cursor[26] {
        w.dropped("OrderInfo", "Ctlg");
    }
    if value.customer_reference_no.is_some() && cursor[27] == 0 {
        w.dropped("OrderInfo", "CustomerReferenceNo");
    }
    if value.supplier_reference_no.is_some() && cursor[28] == 0 {
        w.dropped("OrderInfo", "SupplierReferenceNo");
    }
    if value.delivery_no.is_some() && cursor[29] == 0 {
        w.dropped("OrderInfo", "DeliveryNo");
    }
    if value.delivery_note_voucher_date.is_some() && cursor[30] == 0 {
        w.dropped("OrderInfo", "DeliveryNoteVoucherDate");
    }
    if value.total_weight.is_some() && cursor[31] == 0 {
        w.dropped("OrderInfo", "TotalWeight");
    }
    if value.uw.is_some() && cursor[32] == 0 {
        w.dropped("OrderInfo", "UW");
    }
    if value.provision_date.is_some() && cursor[33] == 0 {
        w.dropped("OrderInfo", "ProvisionDate");
    }
    if value.ctlg_assign.len() > cursor[34] {
        w.dropped("OrderInfo", "CtlgAssign");
    }
    w.extra(&value.extra, "OrderInfo");
    w.close(tag);
    Ok(())
}

