pub fn write_outltxt(w: &mut Writer<'_>, value: &OutlTxt, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("OutlTxt");
    for required in w.required(restriction) {
        let present = match required {
            Name::Style => value.style.is_some(),
            Name::TextOutlTxt => !value.text_outl_txt.is_empty(),
            Name::TextComplement => !value.text_complement.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("OutlTxt", *required, value.node)?;
        }
    }
    w.open(tag);
    if let Some(v) = value.attr_style {
        w.attr_span("style", v);
    }
    w.open_end();
    let order = order_outltxt(w.version());
    let mut cursor = [0usize; 3];
    let groups: &[&[Name]] = &[&[Name::TextOutlTxt, Name::TextComplement]];
    let mut done = [false; 1];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_outltxt(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_outltxt(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_outltxt(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.style.is_some() && cursor[0] == 0 {
        w.dropped("OutlTxt", "Style");
    }
    if value.text_outl_txt.len() > cursor[1] {
        w.dropped("OutlTxt", "TextOutlTxt");
    }
    if value.text_complement.len() > cursor[2] {
        w.dropped("OutlTxt", "TextComplement");
    }
    w.extra(&value.extra, "OutlTxt");
    w.close(tag);
    Ok(())
}

