pub fn write_qtydetermination(
    w: &mut Writer<'_>,
    value: &QtyDetermination,
    tag: &str,
) -> Result<(), WriteError> {
    let restriction = w.restriction("QtyDetermination");
    for required in w.required(restriction) {
        let present = match required {
            Name::PrjInfo => value.prj_info.is_some(),
            Name::QtyDetermInfo => value.qty_determ_info.is_some(),
            Name::DP => value.dp.is_some(),
            Name::OWN => value.own.is_some(),
            Name::CTR => value.ctr.is_some(),
            Name::BoQ => value.boq.is_some(),
            _ => true,
        };
        if !present {
            w.missing("QtyDetermination", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_qtydetermination(w.version());
    let mut cursor = [0usize; 6];
    for name in order {
        while field_qtydetermination(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.prj_info.is_some() && cursor[0] == 0 {
        w.dropped("QtyDetermination", "PrjInfo");
    }
    if value.qty_determ_info.is_some() && cursor[1] == 0 {
        w.dropped("QtyDetermination", "QtyDetermInfo");
    }
    if value.dp.is_some() && cursor[2] == 0 {
        w.dropped("QtyDetermination", "DP");
    }
    if value.own.is_some() && cursor[3] == 0 {
        w.dropped("QtyDetermination", "OWN");
    }
    if value.ctr.is_some() && cursor[4] == 0 {
        w.dropped("QtyDetermination", "CTR");
    }
    if value.boq.is_some() && cursor[5] == 0 {
        w.dropped("QtyDetermination", "BoQ");
    }
    w.extra(&value.extra, "QtyDetermination");
    w.close(tag);
    Ok(())
}

