fn order_qtysplit(version: Version) -> &'static [Name] {
    match version {
        Version::V32 => &[Name::QtyPcnt, Name::Qty, Name::CtlgAssign],
        Version::V33 => &[Name::QtyPcnt, Name::Qty, Name::CtlgAssign],
        _ => &[],
    }
}

