pub fn write_qtysplit(w: &mut Writer<'_>, value: &QtySplit, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("QtySplit");
    for required in w.required(restriction) {
        let present = match required {
            Name::QtyPcnt => value.qty_pcnt.is_some(),
            Name::Qty => value.qty.is_some(),
            Name::CtlgAssign => !value.ctlg_assign.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("QtySplit", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_qtysplit(w.version());
    let mut cursor = [0usize; 3];
    for name in order {
        while field_qtysplit(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.qty_pcnt.is_some() && cursor[0] == 0 {
        w.dropped("QtySplit", "QtyPcnt");
    }
    if value.qty.is_some() && cursor[1] == 0 {
        w.dropped("QtySplit", "Qty");
    }
    if value.ctlg_assign.len() > cursor[2] {
        w.dropped("QtySplit", "CtlgAssign");
    }
    w.extra(&value.extra, "QtySplit");
    w.close(tag);
    Ok(())
}

