pub fn write_quotation(w: &mut Writer<'_>, value: &Quotation, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("Quotation");
    for required in w.required(restriction) {
        let present = match required {
            Name::Kind => value.kind.is_some(),
            Name::PriceFrom => value.price_from.is_some(),
            Name::PriceTo => value.price_to.is_some(),
            Name::Cur => value.cur.is_some(),
            Name::CurLbl => value.cur_lbl.is_some(),
            Name::ConversionRate => value.conversion_rate.is_some(),
            Name::Weight => value.weight.is_some(),
            Name::UW => value.uw.is_some(),
            Name::WeightPart => !value.weight_part.is_empty(),
            Name::WeigthPart => !value.weigth_part.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("Quotation", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_quotation(w.version());
    let mut cursor = [0usize; 10];
    for name in order {
        while field_quotation(w, value, *name, &mut cursor, restriction)? {}
    }
    if value.kind.is_some() && cursor[0] == 0 {
        w.dropped("Quotation", "Kind");
    }
    if value.price_from.is_some() && cursor[1] == 0 {
        w.dropped("Quotation", "PriceFrom");
    }
    if value.price_to.is_some() && cursor[2] == 0 {
        w.dropped("Quotation", "PriceTo");
    }
    if value.cur.is_some() && cursor[3] == 0 {
        w.dropped("Quotation", "Cur");
    }
    if value.cur_lbl.is_some() && cursor[4] == 0 {
        w.dropped("Quotation", "CurLbl");
    }
    if value.conversion_rate.is_some() && cursor[5] == 0 {
        w.dropped("Quotation", "ConversionRate");
    }
    if value.weight.is_some() && cursor[6] == 0 {
        w.dropped("Quotation", "Weight");
    }
    if value.uw.is_some() && cursor[7] == 0 {
        w.dropped("Quotation", "UW");
    }
    if value.weight_part.len() > cursor[8] {
        w.dropped("Quotation", "WeightPart");
    }
    if value.weigth_part.len() > cursor[9] {
        w.dropped("Quotation", "WeigthPart");
    }
    w.extra(&value.extra, "Quotation");
    w.close(tag);
    Ok(())
}

