pub fn write_refgroup(w: &mut Writer<'_>, value: &RefGroup, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("RefGroup");
    for required in w.required(restriction) {
        let present = match required {
            Name::Title => value.title.is_some(),
            Name::BoQItemRef => !value.boq_item_ref.is_empty(),
            Name::BoQCtgyRef => !value.boq_ctgy_ref.is_empty(),
            Name::CostElementRef => !value.cost_element_ref.is_empty(),
            Name::CategoryElementRef => !value.category_element_ref.is_empty(),
            Name::DimensionElementRef => !value.dimension_element_ref.is_empty(),
            Name::ConsortiumMemberRef => !value.consortium_member_ref.is_empty(),
            Name::ProjectBoQItemRef => !value.project_boq_item_ref.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("RefGroup", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_refgroup(w.version());
    let mut cursor = [0usize; 8];
    let groups: &[&[Name]] = &[&[
        Name::BoQItemRef,
        Name::BoQCtgyRef,
        Name::CostElementRef,
        Name::CategoryElementRef,
        Name::DimensionElementRef,
        Name::ConsortiumMemberRef,
        Name::ProjectBoQItemRef,
    ]];
    let mut done = [false; 1];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_refgroup(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_refgroup(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_refgroup(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.title.is_some() && cursor[0] == 0 {
        w.dropped("RefGroup", "Title");
    }
    if value.boq_item_ref.len() > cursor[1] {
        w.dropped("RefGroup", "BoQItemRef");
    }
    if value.boq_ctgy_ref.len() > cursor[2] {
        w.dropped("RefGroup", "BoQCtgyRef");
    }
    if value.cost_element_ref.len() > cursor[3] {
        w.dropped("RefGroup", "CostElementRef");
    }
    if value.category_element_ref.len() > cursor[4] {
        w.dropped("RefGroup", "CategoryElementRef");
    }
    if value.dimension_element_ref.len() > cursor[5] {
        w.dropped("RefGroup", "DimensionElementRef");
    }
    if value.consortium_member_ref.len() > cursor[6] {
        w.dropped("RefGroup", "ConsortiumMemberRef");
    }
    if value.project_boq_item_ref.len() > cursor[7] {
        w.dropped("RefGroup", "ProjectBoQItemRef");
    }
    w.extra(&value.extra, "RefGroup");
    w.close(tag);
    Ok(())
}

