pub fn write_refitems(w: &mut Writer<'_>, value: &RefItems, tag: &str) -> Result<(), WriteError> {
    let restriction = w.restriction("RefItems");
    for required in w.required(restriction) {
        let present = match required {
            Name::Customer => !value.customer.is_empty(),
            Name::CustomerSubNo => !value.customer_sub_no.is_empty(),
            Name::CustomerCtlgAssign => !value.customer_ctlg_assign.is_empty(),
            Name::Supplier => !value.supplier.is_empty(),
            Name::SupplierSubNo => !value.supplier_sub_no.is_empty(),
            Name::SupplierCtlgAssign => !value.supplier_ctlg_assign.is_empty(),
            _ => true,
        };
        if !present {
            w.missing("RefItems", *required, value.node)?;
        }
    }
    w.open(tag);
    w.open_end();
    let order = order_refitems(w.version());
    let mut cursor = [0usize; 6];
    let groups: &[&[Name]] = &[
        &[
            Name::Customer,
            Name::CustomerSubNo,
            Name::CustomerCtlgAssign,
            Name::Supplier,
            Name::SupplierSubNo,
            Name::SupplierCtlgAssign,
        ],
        &[
            Name::Customer,
            Name::CustomerSubNo,
            Name::Supplier,
            Name::SupplierSubNo,
        ],
    ];
    let mut done = [false; 2];
    for name in order {
        let Some(g) = groups.iter().position(|g| g.contains(name)) else {
            while field_refitems(w, value, *name, &mut cursor, restriction)? {}
            continue;
        };
        if done[g] {
            continue;
        }
        done[g] = true;
        for child in value.children.iter().filter(|c| groups[g].contains(c)) {
            field_refitems(w, value, *child, &mut cursor, restriction)?;
        }
        for member in order.iter().filter(|m| groups[g].contains(m)) {
            while field_refitems(w, value, *member, &mut cursor, restriction)? {}
        }
    }
    if value.customer.len() > cursor[0] {
        w.dropped("RefItems", "Customer");
    }
    if value.customer_sub_no.len() > cursor[1] {
        w.dropped("RefItems", "CustomerSubNo");
    }
    if value.customer_ctlg_assign.len() > cursor[2] {
        w.dropped("RefItems", "CustomerCtlgAssign");
    }
    if value.supplier.len() > cursor[3] {
        w.dropped("RefItems", "Supplier");
    }
    if value.supplier_sub_no.len() > cursor[4] {
        w.dropped("RefItems", "SupplierSubNo");
    }
    if value.supplier_ctlg_assign.len() > cursor[5] {
        w.dropped("RefItems", "SupplierCtlgAssign");
    }
    w.extra(&value.extra, "RefItems");
    w.close(tag);
    Ok(())
}

